js.comments.example:
// Сначала сальто
salto();
// salto();   ← эта строка не выполнится

js.for.syntax:
for (let i = 0; i < количество; i++) {
  // команды, которые повторяются
}

js.if.syntax:
if (условие) {
  // если оно верно
} else if (другое условие) {
  // если верно это
} else {
  // если ничего не верно
}

js.if.example:
if (sozrelo()) {
  salto();
} else {
  vyvesti("Ещё не созрело");
}

js.variables.syntax:
let imya = значение;
const imya = значение;
imya = новое_значение;

js.functions.example:
function triSalto() {
  salto();
  salto();
  salto();
}

triSalto();

js.arrow.syntax:
const imya = (a, b) => {
  return a + b;
};

js.lists.syntax:
let s = [значение1, значение2];
s[0]
s.length
s.push(значение);

js.forOf.syntax:
for (let element of spisok) {
  // element — очередной элемент
}

js.mapSet.syntax:
let m = new Map();
m.set(ключ, значение);
m.get(ключ)

let s = new Set();
s.add(значение);
s.has(значение)

js.mapSet.example:
let tseny = new Map();
tseny.set(Rasteniya.Baklazhan, 2);
vyvesti(tseny.get(Rasteniya.Baklazhan));   // 2

js.import.syntax:
// в файле utils
export function imya() { … }

// в файле main
import { imya } from "utils";
